// EventSource is the EventBridge source of every AFS event.
const EventSource = "afs"

// Event is one outbox event. Detail is the EventBridge detail of API contract §7. Data never holds
// a secret value.
type Event struct {
	Type          EventType
	AggregateKind string
	AggregateID   string
	Detail        EventDetail
}

// EventDetail is the envelope {id, occurredAt, teamId, agentId?, poolId?, actor, data}.
type EventDetail struct {
	ID         string         `json:"id"`
	OccurredAt time.Time      `json:"occurredAt"`
	TeamID     string         `json:"teamId"`
	AgentID    string         `json:"agentId,omitempty"`
	PoolID     string         `json:"poolId,omitempty"`
	Actor      string         `json:"actor"`
	Data       map[string]any `json:"data"`
}

// Known reports whether t is a type of API contract §7.
func (t EventType) Known() bool {
	if _, ok := EventEmitters[t]; ok {
		return true
	}
	_, ok := ExtensionEventEmitters[t]
	return ok
}

// NewEvent builds an event for an aggregate. id is the event id (a ULID), now the occurrence time.
// It returns a ValidationError for a type the contract does not list.
func NewEvent(t EventType, id string, now time.Time, actor, teamID, aggregateKind, aggregateID string, data map[string]any) (Event, error) {
	if !t.Known() {
		return Event{}, Validation(FieldError{Field: "eventType", Reason: "not an API contract §7 event type: " + string(t)})
	}
	if data == nil {
		data = map[string]any{}
	}
	return Event{
		Type: t, AggregateKind: aggregateKind, AggregateID: aggregateID,
		Detail: EventDetail{ID: id, OccurredAt: now.UTC(), TeamID: teamID, Actor: actor, Data: data},
	}, nil
}
